/**
 * The shells' copies of the README wordmark.
 *
 * `public/kabmo-wordmark.svg` is the ONE source of the lockup. Three shells draw
 * it natively — a launch splash is platform views, so there is no SVG renderer to
 * hand it to — which means the drawing has to exist once per language. Those
 * copies are GENERATED by `scripts/shell-wordmark.mjs`, and this file is the gate:
 *
 * 1. the generator's output is deterministic and current (`--check` exits 1 when
 *    a copy is stale), which is what CI runs;
 * 2. every number in a copy comes from the SVG, not from a literal in the
 *    generator — a hand-typed `#0b5d3b` would survive an artwork change and paint
 *    the old brand colour forever;
 * 3. the shells' own rules suites re-derive the same numbers from the same file
 *    (`packages/ios/Tests/WordmarkTests.swift`, `packages/macos/Tests/SplashTests.swift`,
 *    `packages/windows/tests/Program.cs`, `packages/linux/rules/wordmark.rs`), so a
 *    stale copy fails on four fronts rather than one.
 */
import { describe, expect, test } from 'bun:test';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { spawnSync } from 'node:child_process';

const ROOT = join(import.meta.dir, '..');
const SVG = readFileSync(join(ROOT, 'public/kabmo-wordmark.svg'), 'utf8');

const COPIES = [
  'packages/macos/Sources/KabmoDesktop/Wordmark.swift',
  'packages/windows/src/KabmoDesktop/Wordmark.cs',
  'packages/linux/src/wordmark_data.rs',
];

describe('scripts/shell-wordmark.mjs', () => {
  test('every copy is current', () => {
    const run = spawnSync(process.execPath, [join(ROOT, 'scripts/shell-wordmark.mjs'), '--check'], {
      cwd: ROOT,
      encoding: 'utf8',
    });
    // `--check` prints the stale file by name, so a failure says which one.
    expect(`${run.stdout}${run.stderr}`).not.toContain('stale');
    expect(run.status).toBe(0);
  });

  test('the artwork itself is unchanged in the ways the copies depend on', () => {
    // The generator reads these five attributes; a rename would make it throw
    // rather than emit a wrong number, but the assertion names them so the
    // failure points at the SVG.
    expect(SVG).toContain('viewBox="0 -128.12 486.38 156.25"');
    expect(SVG).toMatch(/<rect width="156\.25" height="156\.25" y="-128\.12" rx="34\.18" fill="#0b5d3b"/);
    expect(SVG).toContain('stroke-width="17.09"');
    expect(SVG).toContain('stop-color="#f59e0b"');
    expect(SVG).toContain('stop-color="#ea580c"');
    expect(SVG).toContain('.kabmo-mo { fill: #7e7a72; }');
  });

  test('each copy carries the SVG’s numbers, never a hand-typed literal', () => {
    for (const copy of COPIES) {
      const text = readFileSync(join(ROOT, copy), 'utf8');
      // The plate colour and the word ink are the two a human is most likely to
      // retype, and a wrong one draws a plausible mark in the wrong palette.
      expect(text).toContain('0b5d3b');
      expect(text).toContain('7e7a72');
      // The paths are the artwork's own `d` strings, so their first command is
      // in every copy.
      expect(text).toContain('M48.83 -91.5V-8.5');
      expect(text).toContain('M289.88 0L289.88 -75.03');
    }
  });

  test('a copy says it is generated', () => {
    for (const copy of COPIES) {
      expect(readFileSync(join(ROOT, copy), 'utf8')).toContain('GENERATED');
    }
  });
});
